#!/usr/bin/env python3
"""
Round 204o (culprits), 14 October 2026. Needs round 203o.

Pond rows filed; Pull up closes headings; sublayers; lagoon-blue shore glow.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 204o (14 October)\n\nNeeds round 203o (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- The four Clark Labs pond maps sat outside every heading: sectionBody read\n  a heading's title with its small tag (Fishing has one), so no path ever\n  matched a tagged heading and the rows went to the spare place. Titles are\n  now read without the tag; every row filed under a tagged heading moves in.\n- Pull up every layer's dropdown also closes every open heading.\n- Official buildings and Land use indented and smaller under Place names.\n- Raise figures as heights keeps its i on its own line (its note opens\n  over the box); the pull button is as tall as the two switches.\n- Bioluminescent: the river and lake lines are gone; the shore glow is\n  Deep space's lagoon blue (#1F4F7E to #4A9AB6), wide and soft, brightest at\n  the shore and fading out by about 150 m deep.\n"]


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round204o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 203o" not in h.read_text(encoding="utf-8"):
        sys.exit("round204o: round 203o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round204o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/index.html", "map/bodies.html", "map/test.mjs", check=False)
            sys.exit("round204o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round204o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
